#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    int *arr = NULL;
    if (n > 0) {
        arr = (int *)malloc(n * sizeof(int));
        for (int i = 0; i < n; ++i) {
            if (scanf("%d", &arr[i]) != 1) {
                free(arr);
                return 0;
            }
        }
    }
    int k;
    scanf("%d", &k);
    if (n > 0) {
        int r = k % n;
        if (r < 0) r += n;
        for (int i = r; i < n; ++i) {
            if (i != r) putchar(' ');
            printf("%d", arr[i]);
        }
        for (int i = 0; i < r; ++i) {
            putchar(' ');
            printf("%d", arr[i]);
        }
        free(arr);
    }
    putchar('\n');
    return 0;
}
